/**
 * Team invitation email proxy.
 *
 * Hugging Face and some other container platforms block outbound SMTP.
 * This endpoint keeps SMTP transport on Vercel while the invitation content
 * and one-time URL continue to be generated by the PM Brainstorm backend.
 */
const nodemailer = require("nodemailer");

const cleanHeader = (value) =>
  String(value || "")
    .replace(/[\r\n]+/g, " ")
    .trim();

module.exports = async (req, res) => {
  if (req.method !== "POST") {
    return res.status(405).json({ success: false, error: "Method not allowed" });
  }

  const proxyApiKey = process.env.VERCEL_EMAIL_PROXY_KEY;
  if (!proxyApiKey) {
    return res.status(503).json({ success: false, error: "Email proxy is not configured" });
  }
  if (!req.headers["x-api-key"] || req.headers["x-api-key"] !== proxyApiKey) {
    return res.status(401).json({ success: false, error: "Unauthorized" });
  }

  const {
    to_email,
    subject,
    text,
    html,
    smtp_host,
    smtp_port,
    smtp_user,
    smtp_password,
    smtp_from_name,
  } = req.body || {};

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(to_email || ""))) {
    return res.status(400).json({ success: false, error: "Invalid recipient" });
  }
  if (!smtp_host || !smtp_user || !smtp_password) {
    return res.status(400).json({ success: false, error: "Missing SMTP configuration" });
  }
  if (!subject || String(subject).length > 160 || !text || !html || String(html).length > 100000) {
    return res.status(400).json({ success: false, error: "Invalid email content" });
  }

  const port = Number.parseInt(String(smtp_port || "465"), 10);
  if (![465, 587].includes(port)) {
    return res.status(400).json({ success: false, error: "Unsupported SMTP port" });
  }

  try {
    const transporter = nodemailer.createTransport({
      host: smtp_host,
      port,
      secure: port === 465,
      requireTLS: port === 587,
      auth: { user: smtp_user, pass: smtp_password },
      connectionTimeout: 10000,
      greetingTimeout: 8000,
      socketTimeout: 12000,
    });
    const info = await transporter.sendMail({
      from: `"${cleanHeader(smtp_from_name) || "产品脑暴工作台"}" <${smtp_user}>`,
      to: to_email,
      replyTo: smtp_user,
      subject: cleanHeader(subject),
      text,
      html,
    });
    return res.status(200).json({ success: true, message_id: info.messageId });
  } catch (error) {
    console.error("team_invite_email_failed", { name: error?.name || "Error" });
    return res.status(502).json({ success: false, error: "Email delivery failed" });
  }
};
